"""Create Mission Control's VAPID key file ONCE (docs/CONTRACTS.md §12.29: "own VAPID keys, generated by the role").

Usage: <venv python> -I -B vapid_keygen.py <path> <owner> <group> <subject>

If <path> exists in any form (file, symlink, anything), nothing is touched and it prints "exists": a converge
never rotates the keys (a new key pair would orphan every phone's push subscription). Otherwise it writes
{"privateKey": <43 chars>, "publicKey": <87 chars>, "subject": <subject>} (raw P-256 values, base64url without
padding: the house push-store layout MC1's load_vapid() reads) to a temporary file in the same directory, created O_EXCL|O_NOFOLLOW 0600, chowned to <owner>:<group> and chmodded 0640
before anything is written, then hard-links it to <path> (link() fails if <path> appeared meanwhile, so an
existing key is never replaced) and removes the temporary name. It prints "created". It never prints key material.
"""

import base64
import grp
import json
import os
import pwd
import sys

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ec


sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from vapid_check import subject_ok  # noqa: E402  (the one subject rule, next to this script)


def b64u(raw):
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def main(argv):
    if len(argv) != 5:
        print("usage: vapid_keygen.py <path> <owner> <group> <subject>", file=sys.stderr)
        return 2
    path, subject = argv[1], argv[4]
    if not subject_ok(subject):
        print("bad subject: py_vapid won't sign with it (https://<host>, no port or path; or mailto:<address>)",
              file=sys.stderr)
        return 2
    uid, gid = pwd.getpwnam(argv[2]).pw_uid, grp.getgrnam(argv[3]).gr_gid
    if os.path.lexists(path):
        print("exists")
        return 0
    key = ec.generate_private_key(ec.SECP256R1())
    private_raw = key.private_numbers().private_value.to_bytes(32, "big")
    public_raw = key.public_key().public_bytes(
        serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint
    )
    body = json.dumps({"privateKey": b64u(private_raw), "publicKey": b64u(public_raw), "subject": subject},
                      indent=2, sort_keys=True)
    directory = os.path.dirname(os.path.abspath(path))
    tmp = os.path.join(directory, ".vapid-keygen.%d.tmp" % os.getpid())
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    try:
        try:
            os.fchown(fd, uid, gid)
            os.fchmod(fd, 0o640)
            os.write(fd, (body + "\n").encode("ascii"))
            os.fsync(fd)
        finally:
            os.close(fd)
        os.link(tmp, path)
    finally:
        os.unlink(tmp)
    dfd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(dfd)
    finally:
        os.close(dfd)
    print("created")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
